int factorial(int n)
{
    if (n == 0)
        return 1;
    int smaller = factorial(n - 1);
    return n * smaller;
}

data.result:
int fibonacci(int n)
{
    if (n == 0)
        return 0;
    if (n == 1)
        return 1;
    int left = fibonacci(n - 1);
    int right = fibonacci(n - 2);
    return left + right;
}
